this.folded = new Set();
this.spiderFeeds = [];
this.expandedConsoles = new Set();
const root = spiderProps().feedRoot;
if (root) {
  const watchFeeds = cx => {
    if (this.spiderWatching) return;
    this.spiderWatching = true; this.spiderWatchFailed = false;
    cx.spawn(async cx => {
      try {
        let next = watchFolder(root + "/sessions"); this.spiderWatch = next; next.catch(() => {});
        await this.reloadSpiderFeeds(); cx.notify();
        for (;;) {
          await next;
          if (this.spiderClosed) { next.cancel?.(); return; }
          next.cancel?.();
          next = watchFolder(root + "/sessions"); this.spiderWatch = next; next.catch(() => {});
          await this.reloadSpiderFeeds(); cx.notify();
        }
      } catch { this.spiderWatchFailed = true; this.spiderFeedError = "Feed watch unavailable; retrying"; cx.notify(); }
      finally { this.spiderWatching = false; }
    });
  };
  watchFeeds(cx);
  cx.timer.every(FEED_REFRESH_MS, cx => {
    if (this.spiderClosed || this.spiderLoading) return;
    if (this.spiderWatchFailed) watchFeeds(cx);
    else cx.spawn(async cx => { await this.reloadSpiderFeeds(); cx.notify(); });
  });
}

spiderRows(kind, build) {
  try { return build(); }
  catch { (this.spiderRowDiagnostics ??= new Set()).add(kind); return []; }
}

projectChildren(all, addr) {
  const cache = this.spiderRenderRows;
  if (cache?.has(addr)) return cache.get(addr);
  const p = spiderProps();
  const snapshot = this.spiderRenderSnapshot;
  const rows = this.spiderRows("projection", () => agentChildRows(
    projectAgentChildren(all, snapshot?.feeds ?? this.spiderFeeds ?? [], addr, p.labelContract, { ...p.retention, machines: snapshot?.machines ?? machines() }),
    kind => (this.spiderRowDiagnostics ??= new Set()).add(kind)));
  cache?.set(addr, rows);
  return rows;
}

async reloadSpiderFeeds() {
  if (this.spiderClosed) return;
  if (this.spiderLoading || Date.now() - (this.spiderReloadAt ?? -Infinity) < FEED_REFRESH_MS) return;
  this.spiderLoading = true;
  this.spiderReloadAt = Date.now();
  try {
    const p = spiderProps();
    if (!p.feedRoot || !p.nodePath) { this.spiderFeeds = []; this.spiderFeedError = "Session feeds not configured; run doctor"; return; }
    this.spiderReader ??= createFeedReader(p, { exec, fetch: (url, options) => fetch(url, options), timer: this.spiderFeedTimer });
    const loaded = await this.spiderReader.read();
    if (this.spiderClosed) return;
    this.spiderFeeds = loaded.feeds;
    this.spiderFeedsLoaded = true;
    this.spiderFeedError = loaded.errors[0]?.message ?? null;
  } catch { this.spiderFeedError = "Session feeds unavailable; run doctor"; }
  finally { this.spiderLoading = false; }
}

async close() { this.spiderClosed = true; this.spiderWatch?.cancel?.(); await this.spiderReader?.close(); }

openChild(k) {
  if (!k.action) { this.spiderFeedError = "No live endpoint for this child"; return; }
  if (k.action.kind === "peek") { this.peek(k.action.terminal); return; }
  const p = spiderProps();
  if (!p.nodePath || !p.cliPath) { this.spiderFeedError = "Child view unavailable; run doctor"; return; }
  const argv = panelIpcArgv(p.nodePath, p.cliPath, k.action.descriptor, k.action.request);
  return exec(argv[0], argv.slice(1))
    .then(reply => {
      const result = parseSessionIpcReply(reply.stdout);
      this.spiderFeedError = reply.code !== 0 ? "Child view unavailable; run doctor" : result?.ok === false ? (result.message || "Child view unavailable; run doctor") : result?.ok === true && result.op === k.action.request.op ? null : "Child view unavailable; run doctor";
    }, () => { this.spiderFeedError = "Child view unavailable; run doctor"; });
}

